def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        marks = [c for c, v in enumerate(row) if v != background]
        for a, b in zip(marks, marks[1:]):
            if b - a == 2:
                out[r][a + 1] = 2
    return out
